def split_csv(line):
    if not line:
        return ['']

    fields = []
    i = 0

    while i <= len(line):
        if i == len(line):
            fields.append('')
            break

        if line[i] == '"':
            # Quoted field
            field = ''
            i += 1
            while i < len(line):
                if line[i] == '"':
                    if i + 1 < len(line) and line[i + 1] == '"':
                        # Doubled quote
                        field += '"'
                        i += 2
                    else:
                        # End of quoted field
                        i += 1
                        if i == len(line):
                            fields.append(field)
                            break
                        elif line[i] == ',':
                            fields.append(field)
                            i += 1
                            if i == len(line):
                                fields.append('')
                            break
                        else:
                            return None
                else:
                    field += line[i]
                    i += 1
            else:
                # Unterminated quoted field
                return None
        else:
            # Unquoted field
            field = ''
            while i < len(line) and line[i] != ',':
                if line[i] == '"':
                    return None
                field += line[i]
                i += 1
            fields.append(field)
            if i < len(line):
                i += 1
                if i == len(line):
                    fields.append('')

    return fields

